-- Source rows for sales.FactNewBusiness: the logic of the table.
-- Generated by `python -m fde render` from models/gold/sales/FactNewBusiness.sql. Do not edit: change the spec and render again.

IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[FactNewBusinessSource]
AS
with

new_business as (

    select * from [lh_silver].[sales].[newbusinesspolicy]

),

agent as (

    select * from [distribution].[DimAgent]

)

select
    new_business.Policy_BK,
    coalesce(agent.DimAgent_SK, -1) as DimAgent_SK,
    new_business.ProductCode,
    new_business.AnnualPremiumAmount,
    new_business.IssueDate
from new_business
left join agent
    on agent.Agent_BK = new_business.Agent_BK
    and new_business.IssueDate between agent.StartDate and agent.EndDate
GO
